// Presenter-controlled product launch. Product claims come from the supplied launch brief.
export const launchFeatures = [
 {id:'connect',label:'工業串接',en:'CONNECT EVERYTHING',title:'讓現場，接上同一條線。',description:'從相機、設備到資料庫，影像與數據在 WinEdge 匯流。',points:['相機 / RTSP 影像輸入','Modbus · OPC UA · MC Protocol','SQL 資料庫與多種輸入輸出'],summary:'相機、設備、資料庫，一站串接。',note:'先把現場帶進來。介紹影像、工業通訊與 SQL；各項為支援形式，實際配置依設備與專案需求。'},
 {id:'flow',label:'視覺化流程',en:'BUILD THE FLOW',title:'把想法，連成工作流程。',description:'用節點與連線組成作業藍圖，串起輸入、推論與輸出。',points:['在畫布上組合節點','把資料處理與 AI 接成完整流程','工程師不必從零撰寫整段腳本'],summary:'輸入 → 推論 → 輸出，畫出即可串起。',note:'以一條影像流程為例，節點依序入場，再接起資料流。這是功能概念動畫，不是實際編輯器錄影。'},
 {id:'inference',label:'雙路 AI 推論',en:'VISION MEETS DATA',title:'一邊看見，一邊理解。',description:'影像與數據推論並行，在同一平台完成現場判斷。',points:['視覺：物件偵測、物件分割、SAM3','數據：分類、迴歸、時序模型','內建模型節點，接入同一套工作流程'],summary:'視覺 × 數據模型，內建與並行。',note:'上下兩路同步前進，表現視覺與數據模型可並行。SAM3 依新品規劃列入，不附加未提供的效能數字。'},
 {id:'rhythm',label:'通道與節奏',en:'CONTROL EVERY SIGNAL',title:'每筆資料，都有自己的節奏。',description:'從輸入佇列到執行排程，精準安排資料如何對齊、何時開跑。',points:['輸入佇列與背壓：保完整 / 保最新','多來源時序對齊','全速、固定間隔、日 / 週排程'],summary:'佇列、背壓、時序與排程，畫布上調整。',note:'保完整與保最新是兩種取捨。上方展示保留佇列，下方展示只取最新；再依時序對齊與排程送入節點。'},
 {id:'iterate',label:'即時驗證與維運',en:'ITERATE WITHOUT STARTING OVER',title:'邊設計，邊驗證。持續進化。',description:'調整參數，即時預覽與建置。<br>流程運作中，也能靈活維護。',points:['即時預覽與建置執行','執行中熱更新、重建設定','單一節點暫停 / 恢復'],summary:'即時預覽、熱更新、單節點暫停與恢復。',note:'合併原提案的即時預覽與熱更新。動畫中只有中間節點暫停並更新，其餘節點保持運作；不宣稱所有配置均零停機或沒有資料損失。'},
 {id:'dashboard',label:'自由設計看板',en:'DESIGN WHAT YOU NEED',title:'你的產線，你的儀表板。',description:'像設計軟體一樣編排現場資訊，設計完成，一鍵發布。',points:['拖拉元件、圖層分組、對齊與縮放','CSS 與素材客製化','所見即所得，設計完直接發布'],summary:'拖拉排版、CSS 客製，完成即可發布。',note:'看板元件從散開位置進入畫布，對齊、分組後完成發布。畫面以示意數據展示排版能力。'},
 {id:'plugins',label:'Plugin 擴充',en:'READY TO GROW',title:'能力，持續長出來。',description:'節點與看板元件皆可外掛擴充，讓平台跟著現場需求成長。',points:['流程節點與看板元件外掛','延伸既有產線邏輯與客製模型','加入第三方整合'],summary:'節點與看板元件，皆可外掛擴充。',note:'四個模組從外圍接入共用核心，說明可模組化擴充；不加入未提供的外掛市場或 SDK 規格。'},
 {id:'agent',label:'本地 AI Agent',en:'FROM MONITORING TO UNDERSTANDING',title:'讓監控，開始理解。',description:'透過 WinChat 的 RAG、Agent 與 Skill，打造本地端的 Agent 監控系統。',points:['RAG 連結現場知識與操作脈絡','Agent 串接巡檢任務','Skill 重用儀表板與資料統計巡檢方法'],summary:'WinChat RAG + Agent + Skill，本地巡檢。',note:'知識、任務與方法匯入 Agent，再連接 WinEdge 看板與數據巡檢。避免延伸為未授權的自主產線控制。'}
];
export const launchLastStep = launchFeatures.length + 1;
const node=(title,sub='',cls='')=>`<div class="wl-node ${cls}"><strong>${title}</strong>${sub?`<span>${sub}</span>`:''}</div>`;
const arrow='<i class="wl-arrow" aria-hidden="true"><b></b></i>';
const chart=(cls='')=>`<svg class="wl-chart ${cls}" viewBox="0 0 360 110" aria-hidden="true"><path class="wl-chart-grid" d="M0 25H360M0 55H360M0 85H360"/><path class="wl-chart-line" d="M0 77L24 63L45 74L68 33L94 48L119 41L146 59L171 20L198 38L223 30L252 54L275 35L301 44L330 16L360 24"/></svg>`;
const dots=()=>'<span class="wl-packets" aria-hidden="true"><i></i><i></i><i></i><i></i></span>';
function diagram(id){
 if(id==='connect')return `<div class="wl-connect"><div class="wl-connect-inputs">${['相機 / RTSP','Modbus','OPC UA','MC Protocol','SQL'].map((s,i)=>node(s,['影像','設備訊號','工業通訊','PLC','資料庫'][i],'wl-delay-'+i)).join('')}</div><svg class="wl-branch-lines" viewBox="0 0 600 420" preserveAspectRatio="none" aria-hidden="true">${[42,126,210,294,378].map(y=>`<path d="M204 ${y} C285 ${y},295 140,354 140"/>`).join('')}</svg><div class="wl-connect-core">${node('WinEdge','VISION + DATA','wl-core')}${dots()}${node('AI 工作流程','INPUT / INFERENCE / OUTPUT')}</div></div>`;
 if(id==='flow')return `<div class="wl-workflow"><div class="wl-canvas-toolbar"><span>WORKFLOW</span><span class="wl-status">已串接</span></div><div class="wl-flow-line">${node('資料輸入','CAMERA / SENSOR','wl-delay-0')}${arrow}${node('前處理','TRANSFORM','wl-delay-1')}${arrow}${node('AI 推論','INFERENCE','wl-delay-2')}${arrow}${node('資料輸出','OUTPUT','wl-delay-3')}</div><div class="wl-flow-branch">${node('條件判斷','CONDITION')}${arrow}${node('看板 / 紀錄','RESULT')}</div><div class="wl-flow-caption">把現場邏輯，變成看得見的藍圖。</div></div>`;
 if(id==='inference')return `<div class="wl-inference"><div class="wl-inference-lane"><div class="wl-vision-image"><img src="./assets/metal-inspection.png" alt="影像瑕疵檢測的既有產品案例"/><i class="wl-scan"></i><span>VISION</span></div>${arrow}<div class="wl-model-list"><b>物件偵測</b><b>物件分割 / SAM3</b></div></div><div class="wl-inference-lane"><div class="wl-data-plot">${chart()}<span>DATA</span></div>${arrow}<div class="wl-model-list"><b>分類 / 迴歸</b><b>時序模型</b></div></div><div class="wl-inference-out">${dots()}<strong>同一平台，雙路並行。</strong></div></div>`;
 if(id==='rhythm')return `<div class="wl-rhythm"><div class="wl-queue"><label>保完整<span>QUEUE</span></label><div class="wl-queue-items">${[1,2,3,4,5].map(n=>`<i style="--i:${n}">0${n}</i>`).join('')}</div></div><div class="wl-queue latest"><label>保最新<span>LATEST</span></label><div class="wl-queue-items">${[1,2,3,4,5].map(n=>`<i style="--i:${n}">0${n}</i>`).join('')}</div></div><div class="wl-align"><span>來源 A</span><i></i><i></i><i></i><b>時序對齊</b><span>來源 B</span><i></i><i></i><i></i><b>同一時間點</b></div><div class="wl-schedules">${['全速','固定間隔','每日排程','每週排程'].map((s,i)=>`<span style="--i:${i}">${s}</span>`).join('')}</div></div>`;
 if(id==='iterate')return `<div class="wl-iterate"><div class="wl-live-preview"><div><small>PARAMETERS</small><label>調整參數</label><div class="wl-slider"><i></i></div><span>預覽 → 建置執行</span></div><div>${chart()}<span class="wl-preview-result">即時預覽結果</span></div></div><div class="wl-runtime">${node('輸入','RUNNING','wl-running')}${arrow}<div class="wl-update-node"><strong>模型節點</strong><div class="wl-update-states"><span>執行中</span><span>暫停 · 更新設定</span><span>恢復執行</span></div></div>${arrow}${node('輸出','RUNNING','wl-running')}</div><div class="wl-runtime-legend"><i></i>針對單一節點暫停 / 恢復</div></div>`;
 if(id==='dashboard')return `<div class="wl-dashboard"><div class="wl-dashboard-tools"><span>圖層</span><i>圖表</i><i>數值</i><i>狀態</i><i>素材</i></div><div class="wl-board"><div class="wl-board-top"><b>產線總覽</b><span>示意資料</span></div><div class="wl-widget wl-widget-chart"><small>製程趨勢</small>${chart()}</div><div class="wl-widget wl-widget-value"><small>溫度</small><b>24.8<em>°C</em></b></div><div class="wl-widget wl-widget-status"><small>設備狀態</small><b><i></i>運作中</b></div><div class="wl-board-foot"><span>對齊 · 分組 · 縮放</span><b class="wl-publish">發布完成 ✓</b></div></div></div>`;
 if(id==='plugins')return `<div class="wl-plugin-grid">${node('客製模型','CUSTOM MODEL','wl-plug wl-plug-0')}${node('產線邏輯','PROCESS LOGIC','wl-plug wl-plug-1')}${node('WinEdge','PLUGIN CORE','wl-plugin-core')}${node('看板元件','WIDGET','wl-plug wl-plug-2')}${node('第三方整合','INTEGRATION','wl-plug wl-plug-3')}<svg viewBox="0 0 600 400" aria-hidden="true"><path d="M140 100L300 200L460 100M140 300L300 200L460 300"/></svg></div>`;
 return `<div class="wl-agent"><div class="wl-agent-skills">${node('RAG','現場知識','wl-delay-0')}${node('Agent','任務協作','wl-delay-1')}${node('Skill','可重用方法','wl-delay-2')}</div><div class="wl-agent-brain"><span>WinChat</span><strong>本地 Agent</strong><i></i><i></i><i></i></div><div class="wl-agent-targets">${node('儀表板巡檢','DASHBOARD')}${node('資料統計巡檢','DATA REVIEW')}</div><div class="wl-agent-result"><span></span>連結 WinEdge 的現場資訊</div></div>`;
}
const miniIcons={connect:'CAMERA · PLC · SQL',flow:'INPUT → AI → OUTPUT',inference:'VISION ∥ DATA',rhythm:'QUEUE · ALIGN · SCHEDULE',iterate:'PREVIEW ↔ UPDATE',dashboard:'DESIGN → PUBLISH',plugins:'NODES ＋ WIDGETS',agent:'RAG ＋ AGENT ＋ SKILL'};
function summaryHTML(){return `<section class="wl-summary wl-slide"><header><p>EVERY CAPABILITY. ONE WINEDGE.</p><h1>所有能力，在此整合。</h1></header><div class="wl-bento">${launchFeatures.map((f,i)=>`<button class="wl-tile wl-tile-${f.id}" data-launch-feature="${i+1}" style="--i:${i}"><span class="wl-mini-icon">${miniIcons[f.id]}</span><h2>${f.label}</h2><p>${f.summary}</p><b class="wl-tile-arrow" aria-hidden="true">↗</b></button>`).join('')}<div class="wl-bento-core"><span>THE ALL-NEW</span><h2>WinEdge</h2><p>影像 × 數據 × Agent</p><small>模組化，讓可能持續擴展。</small></div></div></section>`}
function featureHTML(f,index){return `<section class="wl-feature wl-slide" data-feature="${f.id}"><div class="wl-feature-copy"><p class="wl-eyebrow">${String(index).padStart(2,'0')} / ${f.en}</p><h1>${f.id==='iterate'?f.title.replace('。','。<br>'):f.id==='rhythm'?f.title.replace('，','，<br>'):f.title}</h1><p class="wl-description">${f.description}</p><ul>${f.points.map((p,i)=>`<li style="--i:${i}">${p}</li>`).join('')}</ul></div><div class="wl-feature-stage"><span class="wl-stage-label">WINEDGE / ${f.label}</span>${diagram(f.id)}<span class="wl-diagram-note">功能流程示意</span></div></section>`}
function heroHTML(){return `<section class="wl-hero wl-slide"><div class="wl-hero-copy"><p class="wl-eyebrow">INTRODUCING THE ALL-NEW</p><h1>WinEdge<span>影像與數據。<br>在此，合而為一。</span></h1><p>從連接現場，到理解與行動。<br>一個平台，組合每一種可能。</p><div class="wl-hero-origin"><span>WinEdge-N</span><i>＋</i><span>WinEdge-V</span><b>→</b><strong>WinEdge</strong></div></div><div class="wl-hero-orbit" aria-hidden="true"></div><span class="wl-hero-caption">ONE EDGE. EVERY POSSIBILITY.</span></section>`}

export function createWinEdgeLaunch({container,onChange=()=>{}}){
 let current=0,active=false,busy=false,generation=0,summarySeen=false,animations=[];
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const mode=()=>current===0?'hero':current===launchLastStep?'summary':'feature';
 function notify(){container.querySelectorAll('[data-launch-step],[data-launch-feature]').forEach(b=>b.disabled=busy);onChange({step:current,last:launchLastStep,mode:mode(),busy,feature:launchFeatures[current-1]})}
 function cancel(){generation++;animations.forEach(a=>a.cancel());animations=[];busy=false}
 function render(){
  container.innerHTML=`<div class="wl-root" data-mode="${mode()}"><div class="wl-content" aria-live="polite" aria-atomic="true">${current===0?heroHTML():current===launchLastStep?summaryHTML():featureHTML(launchFeatures[current-1],current)}</div><nav class="wl-cues" aria-label="WinEdge 發表段落"><button data-launch-step="0" ${current===0?'aria-current="step"':''}>WinEdge</button>${launchFeatures.map((f,i)=>`<button data-launch-step="${i+1}" ${current===i+1?'aria-current="step"':''}><i></i><span>${f.label}</span></button>`).join('')}<button data-launch-step="${launchLastStep}" ${current===launchLastStep?'aria-current="step"':''}>功能總覽</button></nav>${summarySeen&&current>0&&current<launchLastStep?`<button class="wl-back-summary" data-launch-step="${launchLastStep}">回到功能總覽 ↗</button>`:''}<div class="wl-transit" aria-hidden="true"><span>WinEdge</span></div></div>`;
 }
 async function show(next,{instant=false}={}){
  if(!active||busy||next<0||next>launchLastStep||!Number.isInteger(next))return false;
  cancel();const ticket=generation;busy=true;notify();
  const outgoing=container.querySelector('.wl-content');
  if(!reduced&&!instant&&outgoing){const a=outgoing.animate([{opacity:1,transform:'translateY(0) scale(1)'},{opacity:0,transform:'translateY(-18px) scale(.985)'}],{duration:280,easing:'ease-in',fill:'forwards'});animations.push(a);await a.finished.catch(()=>{});if(ticket!==generation||!active)return false}
  current=next;if(current===launchLastStep)summarySeen=true;render();notify();
  if(!reduced&&!instant){const content=container.querySelector('.wl-content'),sweep=container.querySelector('.wl-transit');const a=content.animate([{opacity:0,transform:'translateY(25px) scale(.97)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:950,easing:'cubic-bezier(.16,1,.3,1)'});const b=sweep.animate([{opacity:0,transform:'translateX(-110%) skewX(-12deg)'},{opacity:.8,offset:.28},{opacity:0,transform:'translateX(110%) skewX(-12deg)'}],{duration:850,easing:'ease-in-out'});animations.push(a,b);b.finished.catch(()=>{});await a.finished.catch(()=>{});if(ticket!==generation||!active)return false}
  animations=[];busy=false;notify();return true;
 }
 container.addEventListener('click',e=>{const b=e.target.closest('[data-launch-step],[data-launch-feature]');if(b&&active){show(Number(b.dataset.launchStep??b.dataset.launchFeature))}});
 return {start(){cancel();active=true;current=0;summarySeen=false;render();notify()},stop(){active=false;cancel();container.querySelectorAll('.wl-root').forEach(e=>e.remove())},next(){if(!active)return false;if(busy)return true;if(current===launchLastStep)return false;show(current+1);return true},previous(){if(!active||current===0&&!busy)return false;if(!busy)show(current-1);return true},state:()=>({current,active,busy})};
}
